const PHASE_KEYS = [
  "UNIT_TESTS",
  "API_TESTS",
  "E2E_TESTS",
  "SECURITY",
  "INTEGRATION",
  "CODE_REVIEW",
  "WEB_RESEARCH",
  "PERFORMANCE",
  "ACCESSIBILITY",
  "REGRESSION",
  "UAT",
] as const;

function buildPhases(env: Readonly<Record<string, string | undefined>>): string {
  const enabled: string[] = [];
  for (const key of PHASE_KEYS) {
    if (envBool(env, `PHASE_${key}`)) enabled.push(key);
  }
  return enabled.join(",");
}

