// ---------------------------------------------------------------------------

function loadLedgerContext(cwd: string): string {
  const dir = resolve(cwd, ".loki/memory/ledgers");
  if (!existsSync(dir)) return "";
  let entries: string[];
  try {
    entries = readdirSync(dir).filter((f) => f.startsWith("LEDGER-") && f.endsWith(".md"));
  } catch {
    return "";
  }
  if (entries.length === 0) return "";
  // bash `ls -t` sorts by mtime descending. Stat each file and pick newest.
  let newest: { path: string; mtimeMs: number } | null = null;
  for (const name of entries) {
    const p = resolve(dir, name);
    try {
      const st = statSync(p);
      if (newest === null || st.mtimeMs > newest.mtimeMs) {
        newest = { path: p, mtimeMs: st.mtimeMs };
      }
    } catch {
      /* skip */
    }
  }
  if (newest === null) return "";
  return readLinesSafe(newest.path, 100) ?? "";
}

// ---------------------------------------------------------------------------
// load_handoff_context (run.sh:8225). Newest .json (within 1 day, bash uses
// `find -mtime -1`); falls back to newest .md (head -80 lines).
// We mirror the touch-on-load semantics by NOT enforcing the mtime filter --
// the bash test harness touches files just before invocation, so it is
// effectively "newest of all".
// ---------------------------------------------------------------------------

async function loadHandoffContext(cwd: string): Promise<string> {
  const dir = resolve(cwd, ".loki/memory/handoffs");
  if (!existsSync(dir)) return "";
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return "";
  }

  const pickNewest = (suffix: string): string | null => {
    let newest: { path: string; mtimeMs: number } | null = null;
    for (const name of entries) {
      if (!name.endsWith(suffix)) continue;
      const p = resolve(dir, name);
      try {
        const st = statSync(p);
        if (newest === null || st.mtimeMs > newest.mtimeMs) {
          newest = { path: p, mtimeMs: st.mtimeMs };
        }
      } catch {
        /* skip */
      }
    }
    return newest === null ? null : newest.path;
  };

  const json = pickNewest(".json");
  if (json !== null) {
    // run.sh:8233 -- format JSON via Python. We replicate the format in TS
    // since it is a stable schema (no need to shell out).
    const raw = readFileSafe(json);
    if (raw === null) return "";
    try {
      const h = JSON.parse(raw) as Record<string, unknown>;
      const parts: string[] = [];
      const ts = String(h["timestamp"] ?? "unknown");
      const reason = String(h["reason"] ?? "unknown");
      parts.push(`Handoff from ${ts} (reason: ${reason})`);
      parts.push(`Iteration: ${String(h["iteration"] ?? 0)}`);
      const files = h["files_modified"];
      if (Array.isArray(files) && files.length > 0) {
        parts.push(`Modified files: ${files.slice(0, 10).map(String).join(", ")}`);
      }
      const tasks = (h["task_status"] as Record<string, unknown> | undefined) ?? {};
      parts.push(
        `Tasks - pending: ${String(tasks["pending"] ?? 0)}, completed: ${String(tasks["completed"] ?? 0)}`,
      );
      const oq = h["open_questions"];
      if (Array.isArray(oq)) {
        for (const q of oq) parts.push(`Open question: ${String(q)}`);
      }
      const bl = h["blockers"];
      if (Array.isArray(bl)) {
        for (const b of bl) parts.push(`Blocker: ${String(b)}`);
      }
      return parts.join(" | ");
    } catch {
      return "";
    }
  }

  const md = pickNewest(".md");
  if (md !== null) {
    return readLinesSafe(md, 80) ?? "";
  }
  return "";
}

// ---------------------------------------------------------------------------
// load_startup_learnings (run.sh:8282). Reads .loki/state/memory-context.json,
// emits "STARTUP LEARNINGS (pre-loaded):" header + top 5 memories formatted
// as `- [source|score] summary[:100]`.
// ---------------------------------------------------------------------------

// RUN-25 iter 2: --skip-memory maps to LOKI_SKIP_MEMORY=true (bash autonomy/
// loki:1630, read at :664). Honor it on the Bun route too so the flag actually
// takes effect (it was accepted by start.ts but previously unread here -- a
// hidden capability loss under the loop-flip). Byte-lock-safe: the fixtures never
// set LOKI_SKIP_MEMORY and never ship memory-context.json, so the default (unset)
// path is byte-identical.
function skipMemory(): boolean {
  const v = process.env["LOKI_SKIP_MEMORY"];
  return v === "true" || v === "1";
}

function loadStartupLearnings(cwd: string): string {
  if (skipMemory()) return "";
  const path = resolve(cwd, ".loki/state/memory-context.json");
  const raw = readFileSafe(path);
  if (raw === null) return "";
  try {
    const data = JSON.parse(raw) as Record<string, unknown>;
    if (typeof data !== "object" || data === null) return "";
    if (typeof data["memory_count"] !== "number") return "";
    const memories = data["memories"];
    if (!Array.isArray(memories) || memories.length === 0) return "";
    const lines: string[] = ["STARTUP LEARNINGS (pre-loaded):"];
    for (const m of memories.slice(0, 5)) {
      if (typeof m !== "object" || m === null) continue;
      const mo = m as Record<string, unknown>;
      const source = String(mo["source"] ?? "unknown");
      const summaryRaw = String(mo["summary"] ?? "");
      const summary = summaryRaw.slice(0, 100);
      const score = mo["score"] ?? 0;
      if (summary.length > 0) lines.push(`- [${source}|${String(score)}] ${summary}`);
    }
    return lines.join("\n");
  } catch {
    return "";
  }
}

// ---------------------------------------------------------------------------
// retrieve_memory_context (run.sh:8359). Stub: returns empty unless
// .loki/memory/index.json exists. The full implementation shells out to
// Python with the in-tree memory package; for prompt-parity in fixtures
// (which never include index.json) the empty-return path is sufficient.
// ---------------------------------------------------------------------------

function retrieveMemoryContext(cwd: string): string {
  if (skipMemory()) return ""; // RUN-25 iter 2: --skip-memory / LOKI_SKIP_MEMORY
  const indexPath = resolve(cwd, ".loki/memory/index.json");
  if (!existsSync(indexPath)) return "";
  // For now, do not attempt to invoke the Python retrieval pipeline from
  // build_prompt -- a follow-up port wires it in. Returning empty matches
  // bash when the Python path errors out (every fixture exercises this).
  return "";
}

// ---------------------------------------------------------------------------
// load_queue_tasks (run.sh:8823). Reads .loki/queue/in-progress.json (if
// present) AND .loki/queue/pending.json. Each is parsed and the first 3
// tasks are formatted in either rich (PRD-source) or legacy form. Combined
// with "IN-PROGRESS TASKS (EXECUTE THESE):\n" / "PENDING:\n" headers and
// joined with "\n---\n".
// ---------------------------------------------------------------------------

interface QueueTask {
  id?: string;
  source?: string;
  type?: string;
  title?: string;
  description?: string;
  acceptance_criteria?: unknown[];
  user_story?: string;
  payload?: Record<string, unknown> | string | null;
}

function extractQueueTasks(path: string, prefix: string): string {
  const raw = readFileSafe(path);
  if (raw === null) return "";
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return "";
  }
  let tasks: unknown;
  if (Array.isArray(parsed)) {
    tasks = parsed;
  } else if (
    parsed !== null &&
    typeof parsed === "object" &&
    Object.prototype.hasOwnProperty.call(parsed, "tasks")
  ) {
    // v7.5.9 (council R4#1 follow-up): use hasOwnProperty.call to avoid
    // walking Object.prototype chain on JSON-parsed input.
    tasks = (parsed as Record<string, unknown>)["tasks"];
  } else {
    tasks = parsed;
  }
  if (!Array.isArray(tasks)) return "";

  const results: string[] = [];
  const slice = tasks.slice(0, 3);
  for (let i = 0; i < slice.length; i++) {
    const t = slice[i];
    if (t === null || typeof t !== "object") continue;
    const task = t as QueueTask;
    // WT4/H7 (FIX-W4-E): QueueTask fields are typed string?/etc but NOT enforced
    // at runtime -- malformed JSON (e.g. {"id":123}) yields a number, and a bare
    // `.startsWith`/`.replace` on it throws. An uncaught throw here propagates to
    // autonomous.ts and discards the ENTIRE real prompt (RARV/SDLC/PRD/queue/gates)
    // for that iteration, falling back to the stub. Coerce every string-field
    // access defensively with String(... ?? default) so a malformed entry degrades
    // (coerced/skipped), never throws away the whole prompt.
    const taskId = String(task.id ?? "unknown");
    const source = String(task.source ?? "");

    if (source === "prd" || taskId.startsWith("prd-")) {
      const title = String(task.title ?? "Task");
      const lines: string[] = [`${prefix}[${i + 1}] ${taskId}: ${title}`];
      const desc = String(task.description ?? "");
      if (desc.length > 0 && desc !== title) {
        let descShort = desc.replace(/\n/g, " ").replace(/\r/g, "").slice(0, 300);
        if (desc.length > 300) descShort += "...";
        lines.push(`  Description: ${descShort}`);
      }
      const criteria = task.acceptance_criteria;
      if (Array.isArray(criteria) && criteria.length > 0) {
        const criteriaStr = criteria.slice(0, 5).map((c) => String(c)).join("; ");
        lines.push(`  Acceptance: ${criteriaStr}`);
      }
      const story = String(task.user_story ?? "");
      if (story.length > 0) lines.push(`  User Story: ${story}`);
      results.push(lines.join("\n"));
    } else {
      const taskType = String(task.type ?? "unknown");
      let action = "";
      const payload = task.payload;
      if (payload !== null && payload !== undefined && typeof payload === "object") {
        const pl = payload as Record<string, unknown>;
        action = String(pl["action"] ?? pl["goal"] ?? "");
      } else if (payload !== null && payload !== undefined) {
        action = String(payload);
      }
      if (action.length === 0) {
        action = String(task.title ?? task.description ?? "");
      }
      action = action.replace(/\n/g, " ").replace(/\r/g, "").slice(0, 500);
      // bash bug: `len(str(action)) > 500` after slicing always false; we
      // mirror the practical effect (no ellipsis appended).
      results.push(`${prefix}[${i + 1}] id=${taskId} type=${taskType}: ${action}`);
    }
  }
  return results.join("\n");
}

function loadQueueTasks(cwd: string): string {
  const inProgressPath = resolve(cwd, ".loki/queue/in-progress.json");
  const pendingPath = resolve(cwd, ".loki/queue/pending.json");
  const hasIn = existsSync(inProgressPath);
  const hasPending = existsSync(pendingPath);
  if (!hasIn && !hasPending) return "";

  const inProgress = hasIn ? extractQueueTasks(inProgressPath, "TASK") : "";
  const pending = hasPending ? extractQueueTasks(pendingPath, "PENDING") : "";
  const out: string[] = [];
  if (inProgress.length > 0) out.push(`IN-PROGRESS TASKS (EXECUTE THESE):\n${inProgress}`);
  if (pending.length > 0) out.push(`PENDING:\n${pending}`);
  return out.join("\n---\n");
}

// ---------------------------------------------------------------------------
// Gate failure context (run.sh:9007-9023).
// ---------------------------------------------------------------------------

async function buildGateFailureContext(
  cwd: string,
  env: Record<string, string | undefined> = process.env,
): Promise<string> {
  let ctx = "";

  // Gate-failure injection (run.sh:9007-9023 / 12296-12331). Guarded on
  // gate-failures.txt presence: when absent, this whole block is skipped and
  // ctx stays "" (byte-identical to the prior early-return behavior).
  const gfPath = resolve(cwd, ".loki/quality/gate-failures.txt");
  // WT4/L1 (FIX-W4-E): cap the read so a pathological multi-MB gate-failures.txt
  // (e.g. a prior-iteration stack-trace dump) cannot balloon the context window.
  // Every OTHER reader in this module caps (readBytesSafe 4000/8000/16000,
  // readLinesSafe 80/100, slice 200/300/500); this one was uncapped. The bash
  // route still does an uncapped `cat` (autonomy/run.sh:12412) -- this 8000-byte
  // cap matches the most-capping siblings and never triggers on the parity
  // fixtures (largest is fixture-36 at 2442 bytes), so the parity contract stays
  // green while the pathological case is bounded. FOLLOW-UP: apply the same cap
  // to the bash route at run.sh:12412 (cannot edit that file here).
  const failures = readBytesSafe(gfPath, 8000);
  if (failures !== null) {
    // readBytesSafe already strips trailing newlines (parity with bash printf).
    ctx = `QUALITY GATE FAILURES FROM PREVIOUS ITERATION: [${failures}]. `;

    const saPath = resolve(cwd, ".loki/quality/static-analysis.json");
    if (existsSync(saPath)) {
      const summary = await readSummaryField(saPath);
      if (summary.length > 0) ctx += `Static analysis: ${summary}. `;
    }
    const trPath = resolve(cwd, ".loki/quality/test-results.json");
    if (existsSync(trPath)) {
      const summary = await readSummaryField(trPath);
      if (summary.length > 0) ctx += `Tests: ${summary}. `;
    }

    ctx += `FIX THESE ISSUES BEFORE PROCEEDING WITH NEW WORK.`;
  }

  // Structured per-finding records (severity, file:line, reviewer) from the
  // previous iteration's per-reviewer files.
  //
  // Surfaced INDEPENDENTLY of gate-failures.txt, for exactly the reason the
  // semantic and invariant blocks below were hoisted: a reviewer council can
  // BLOCK without any gate writing gate-failures.txt, and nesting this under
  // that guard silently drops precisely that case. Verified by execution --
  // with real reviewer findings present but no gate-failures.txt, the prompt
  // contained neither the offending file nor the finding text, so the model
  // was told to fix problems without being told which. That is a blind retry:
  // the model re-derives what is wrong from scratch every iteration, which is
  // both the slowest and the least accurate way to converge.
  //
  // This is the single highest-value accuracy lever in the loop. Telling a
  // model precisely what a reviewer found is what turns iteration 2 into a fix
  // rather than a guess.
  // Read the opt-out from the RUN's env, not process.env. buildPrompt is
  // driven by ctx.env, and a run that sets LOKI_INJECT_FINDINGS=0 there must
  // be honoured -- reading process.env silently ignored the operator's opt-out.
  if (envStr(env, "LOKI_INJECT_FINDINGS", "") !== "0") {
    const findingsBlock = await buildStructuredFindingsBlock(cwd);
    if (findingsBlock.length > 0) {
      ctx += `\n\n${findingsBlock}\n`;
      ctx += `FIX THESE ISSUES BEFORE PROCEEDING WITH NEW WORK.\n`;
    }
  }

  // P1-3 semantic test-authenticity findings (run.sh:12338-12351). Surfaced
  // INDEPENDENTLY of gate-failures.txt: the completion-promise arm writes
  // semantic-findings.txt without appending any gate token, so nesting this
  // under the gate-failures guard would silently drop exactly that case. The
  // Bun route's runSemanticTests (quality_gates.ts) writes this file; this is
  // the consumer that reaches parity with bash. Absent/empty -> nothing added.
  ctx += buildSemanticFindingsBlock(cwd);

  // P1-4 invariant-violation findings. Surfaced INDEPENDENTLY of
  // gate-failures.txt, mirroring the semantic block above. The bash route's
  // enforce_invariant_integrity (run.sh:8422) WRITES
  // .loki/quality/invariant-findings.txt -- the blocking write CRITICAL/HIGH
  // (run.sh:8451) and the advisory write MED/LOW (run.sh:8464) -- but neither
  // route had a prompt-reader: run.sh only logs the path (run.sh:15565), and the
  // Bun runInvariants (quality_gates.ts:810) deliberately does NOT persist the
  // file today, calling out a build_prompt.ts reader as the prerequisite
  // follow-up (quality_gates.ts:786-794). This is that reader: it surfaces the
  // per-finding text written by the bash gate into the next-iteration prompt.
  // It also primes the Bun route -- once quality_gates.ts persists the file (its
  // named follow-up), this consumer surfaces it with no further change.
  // Absent/empty -> nothing added.
  ctx += buildInvariantFindingsBlock(cwd);

  return ctx;
}

function buildGateEscalationContext(cwd: string): string {
  const raw = safeReadLocal(resolve(cwd, ".loki/signals/GATE_ESCALATION.json"));
  if (raw === null) return "";

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return "";
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return "";
  const data = parsed as Record<string, unknown>;
  if (data["action"] !== "escalate") return "";

  const gate = data["gate"];
  const count = data["count"];
  const threshold = data["threshold"];
  const artifact = data["latest_artifact"];
  if (typeof gate !== "string" || !/^[A-Za-z0-9_.-]+$/.test(gate)) return "";
  if (typeof count !== "number" || !Number.isInteger(count) || count < 1) return "";
  if (typeof threshold !== "number" || !Number.isInteger(threshold) || threshold < 1) return "";
  if (artifact !== null && artifact !== undefined && typeof artifact !== "string") return "";

  const artifactText =
    typeof artifact === "string" && artifact.length > 0
      ? `Inspect latest artifact: ${artifact}.`
      : "No latest artifact was recorded.";
  return (
    `REPEATED_GATE_BLOCKER (PRIORITY): action=escalate gate=${gate} count=${count} threshold=${threshold}. ` +
    `Change implementation strategy on this attempt. ${artifactText} Resolve the root blocker before new work. ` +
    "Do not suppress or filter console errors or React act warnings, mock those signals, or weaken tests or assertions."
  );
}

// ---------------------------------------------------------------------------
// SLICE 6c self-heal (mirror of run.sh _loki_build_self_heal_hint).
// ---------------------------------------------------------------------------
// Route the prior iteration's classified error signature into this iteration's
// prompt so the loop fixes forward. Opt-in via LOKI_SELF_HEAL (default 0 --
// stock runs are byte-identical). Reads .loki/state/LAST_ERROR.json, emits the
// same hint string as bash, then archives-then-clears the record so the hint
// injects exactly ONCE. "unknown"/empty error_class is NOT actionable -> no
// hint. Best-effort; any failure returns "".
function buildSelfHealContext(cwd: string): string {
  if (process.env["LOKI_SELF_HEAL"] !== "1") return "";
  const src = resolve(cwd, ".loki/state/LAST_ERROR.json");
  const raw = safeReadLocal(src);
  if (raw === null) return "";
  let rec: unknown;
  try {
    rec = JSON.parse(raw);
  } catch {
    return "";
  }
  if (rec === null || typeof rec !== "object") return "";
  const r = rec as Record<string, unknown>;
  const ec = String(r["error_class"] ?? "").trim();
  if (ec === "" || ec === "unknown") return "";
  const brief = String(r["brief"] ?? "").trim();
  const it = r["iteration"] ?? "?";
  const hint =
    `SELF_HEAL_HINT: the previous iteration (#${it}) failed with error_class=${ec}. ` +
    `${brief} Address this specific failure FIRST before any new work.`;
  // Archive-then-clear so it injects once (LEARN-FORWARD parity with bash
  // _loki_archive_last_error, run.sh:1180): the record lands in
  // failure-history.jsonl before the single file is removed. Mirror bash EXACTLY:
  // read the existing history, append this record, keep only the most recent 50
  // entries (bounded -- never grows unbounded), and write atomically via a
  // temp file + rename (no partial-write window on a concurrent reader).
  try {
    const hist = resolve(cwd, ".loki/state/failure-history.jsonl");
    let lines: string[] = [];
    const prev = safeReadLocal(hist);
    if (prev !== null) {
      lines = prev.split("\n").filter((ln) => ln.trim() !== "");
    }
    lines.push(JSON.stringify(rec));
    lines = lines.slice(-50);
    const tmp = resolve(dirname(hist), `.failure-history.${process.pid}.tmp`);
    writeFileSync(tmp, lines.join("\n") + "\n");
    renameSync(tmp, hist);
  } catch {
    /* best-effort */
  }
  try {
    rmSync(src, { force: true });
  } catch {
    /* best-effort */
  }
  return hint;
}

function safeReadLocal(path: string): string | null {
  try {
    if (!existsSync(path)) return null;
    return readFileSync(path, "utf-8");
  } catch {
    return null;
  }
}

// P1-3 helper: surface the specific semantic test-authenticity findings
// (which fake test, which line) that quality_gates.ts wrote to
// .loki/quality/semantic-findings.txt. Byte-for-byte mirror of
// run.sh:12338-12351 -- grep severity-tagged lines, head -20, prepend the
// exact bash prefix (including its leading space). Returns "" when the file
// is absent or has no severity-tagged lines (e.g. only the header line).
function buildSemanticFindingsBlock(cwd: string): string {
  const path = resolve(cwd, ".loki/quality/semantic-findings.txt");
  const raw = readFileSafe(path);
  if (raw === null) return "";
  const lines = raw
    .split("\n")
    .filter((l) => /\[(CRITICAL|HIGH|MEDIUM|LOW)\]/.test(l))
    .slice(0, 20);
  if (lines.length === 0) return "";
  // Prefix copied verbatim from run.sh:12348, including the leading space.
  return ` SEMANTIC TEST-AUTHENTICITY FINDINGS (fix the fake tests; an assertion must verify a value that flows through the code under test, not echo a literal back): ${lines.join("\n")}`;
}

// P1-4 helper: surface the specific invariant-violation findings (which
// invariant, which file/property) that enforce_invariant_integrity
// (run.sh:8422) wrote to .loki/quality/invariant-findings.txt. Structural
// mirror of buildSemanticFindingsBlock: read the file, keep only severity-tagged
// lines, head -20 cap, prepend an actionable header (with a leading space,
// matching the semantic block so concatenation reads cleanly). The two bash
// writer headers ("# Invariant findings (...)" / "# Invariant advisory findings
// (...)") carry no severity token, so the filter drops them for both the
// blocking and advisory writes. Unlike semantic, no prompt-builder on either
// route had a reader (run.sh only logs the path; quality_gates.ts does not
// persist the file -- quality_gates.ts:786-794), so the header below is newly
// authored actionable text, not a verbatim bash prefix.
// Returns "" when the file is absent or has no severity-tagged lines.
function buildInvariantFindingsBlock(cwd: string): string {
  const path = resolve(cwd, ".loki/quality/invariant-findings.txt");
  const raw = readFileSafe(path);
  if (raw === null) return "";
  const lines = raw
    .split("\n")
    .filter((l) => /\[(CRITICAL|HIGH|MEDIUM|LOW)\]/.test(l))
    .slice(0, 20);
  if (lines.length === 0) return "";
  return ` INVARIANT VIOLATION FINDINGS (fix the violated invariants; a property/metamorphic invariant that the code under test must always uphold is currently broken): ${lines.join("\n")}`;
}

// Locate a file shipped inside the engine install, independent of how deep this
// module sits. Dev runs from loki-ts/src/runner/; the shipped package runs from
// the bundled loki-ts/dist/. Returns null when not found (engine files absent).
function findEngineFile(rel: string): string | null {
  let dir = import.meta.dir;
  for (let i = 0; i < 6; i++) {
    const candidate = resolve(dir, rel);
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

// Close the eval feedback loop: surface the run's OWN efficiency trend
// (.loki/metrics/efficiency/iteration-N.json) into the next prompt, so the agent
// producing the cost can finally see it. Those records have been written every
// iteration for the engine's entire life and read back only by a stop-only budget
// breaker and an offline report -- never by the agent.
//
// SINGLE RENDERER, BOTH ROUTES. The text is produced by
// autonomy/lib/iteration_attribution.py --prompt-block, which both this function
// and bash build_prompt() shell out to. That module already owns the
// progress/rework bucketing (and is already imported by proof-generator.py:1097),
// so this is an established shared-library seam, not a new one. Rendering in
// each route independently would be two renderers that must be kept
// byte-identical forever; one renderer is identical by construction.
//
// ponytail: one python3 subprocess per prompt build. The ceiling is fine -- the
// same function already shells to python3 for readSummaryField's fallback, and it
// runs alongside a multi-second model call. Port to readEfficiencyDir (budget.ts)
// only if prompt-build latency ever shows up in a profile.
//
// Returns "" on absent/empty metrics, a non-zero exit, or a missing python3, so
// an unmeasured run adds NOTHING to the prompt (no dangling header).
//
// DELIBERATELY NOT on the PROVIDER_DEGRADED path (Codex / Aider), same as
// goalSharpening above: those providers carry a minimal instruction set by
// design, and this is steering advice, not a requirement. Mirrored in bash --
// the degraded assembly there does not emit $efficiency_trend either.
async function buildEfficiencyTrend(
  cwd: string,
  env: Readonly<Record<string, string | undefined>>,
): Promise<string> {
  // Opt-out read from the RUN's env, never process.env. Default ON.
  // Accepts BOTH spellings because this repo uses both conventions for toggles
  // (LOKI_AUTO_DOCS=false alongside LOKI_GOAL_SCORING=0). Honouring only "0"
  // means an operator who writes the documented-elsewhere "false" gets a silent
  // no-op opt-out, which is worse than no flag at all. Byte-mirrored in
  // run.sh's build_prompt().
  const trendOptOut = envStr(env, "LOKI_EVAL_TREND", "").trim().toLowerCase();
  if (trendOptOut === "0" || trendOptOut === "false") return "";
  // Resolve the renderer from the ENGINE install dir, not from cwd. cwd is the
  // user's project, which has no autonomy/lib/ -- bash uses $SCRIPT_DIR
  // (run.sh:204) for exactly this reason. Resolving from cwd would make the Bun
  // route silently render nothing on every real run while still passing a test
  // whose fixture happens to sit inside this repo.
  //
  // Walk UP rather than hardcode a depth: this module runs from
  // loki-ts/src/runner/ in dev but from the bundled loki-ts/dist/ in the shipped
  // package, and those are different distances from the repo root. A fixed
  // "../../../" is correct for exactly one of them and silently resolves to a
  // nonexistent path (rendering nothing, forever) for the other.
  const script = findEngineFile("autonomy/lib/iteration_attribution.py");
  if (script === null) return "";
  const lokiDir = resolve(cwd, ".loki");
  if (!existsSync(lokiDir)) return "";
  try {
    // Import the module and call prompt_block directly -- the same entry point
    // `--prompt-block` uses, and the same one proof-generator.py imports.
    // runInline is already imported by this file (readSummaryField's fallback),
    // so no new util export is needed.
    const src = [
      "import sys",
      `sys.path.insert(0, ${JSON.stringify(dirname(script))})`,
      "from iteration_attribution import prompt_block",
      `sys.stdout.write(prompt_block(${JSON.stringify(lokiDir)}))`,
    ].join("\n");
    const r = await runInline(src, { cwd, timeoutMs: 10_000 });
    if (r.exitCode !== 0) return "";
    return r.stdout.trimEnd();
  } catch {
    return "";
  }
}

// Phase 1 helper: read structured findings from the most recent review dir
// and render them as a prompt-ready block. Lives here (not in
// build_prompt_helpers.ts) to keep the env-flag gate in one file. Imports
// are dynamic to avoid loading the whole findings_injector module on every
// prompt build when the flag is off.
async function buildStructuredFindingsBlock(cwd: string): Promise<string> {
  try {
    const mod = await import("./findings_injector.ts");
    const lokiDir = resolve(cwd, ".loki");
    const result = mod.loadPreviousFindings(lokiDir);
    if (result.findings.length === 0) return "";
    return mod.renderFindingsForPrompt(result.findings);
  } catch {
    // If the module fails to load for any reason (e.g. mid-port races),
    // fall back to the bare token-list path silently.
    return "";
  }
}

async function readSummaryField(path: string): Promise<string> {
  // Matches run.sh:9013-9020: `python3 -c "import json; d=json.load(...); print(d.get('summary',''))"`.
  const raw = readFileSafe(path);
  if (raw === null) return "";
  try {
    const data = JSON.parse(raw) as Record<string, unknown>;
    return String(data["summary"] ?? "");
  } catch {
    // Bash `|| echo ""` swallows the error. Fall back to Python (rare).
    try {
      const r = await runInline(
        `import json; d=json.load(open(${JSON.stringify(path)})); print(d.get('summary',''))`,
      );
      return r.stdout.replace(/\n$/, "");
    } catch {
      return "";
    }
  }
}

