// ---------------------------------------------------------------------------
// Resolved context (ledger + handoff + startup learnings + memory ctx).
// ---------------------------------------------------------------------------

interface ResolvedSections {
  contextSection: string;
  gateFailureContext: string;
  gateEscalationContext: string;
  selfHealContext: string;
  humanDirective: string;
  queueTasks: string;
  appRunnerInfo: string;
  playwrightInfo: string;
  bmadContext: string;
  openspecContext: string;
  mirofishContext: string;
  magicContext: string;
  checklistStatus: string;
  efficiencyTrend: string;
}

async function resolveDynamicSections(
  opts: BuildPromptOpts,
  targetDir: string,
): Promise<ResolvedSections> {
  const { ctx, retry, prd, iteration } = opts;
  const env = ctx.env;

  // context_injection (run.sh:8965-9004) -- ledger+handoff (resume only),
  // startup learnings (iteration==1 only), and retrieved memory.
  let contextInjection = "";
  if (retry > 0) {
    const ledger = loadLedgerContext(ctx.cwd);
    const handoff = await loadHandoffContext(ctx.cwd);
    if (ledger.length > 0) contextInjection = `PREVIOUS_LEDGER_STATE: ${ledger}`;
    if (handoff.length > 0) contextInjection = `${contextInjection} RECENT_HANDOFF: ${handoff}`;
  }
  if (iteration === 1) {
    const startup = loadStartupLearnings(ctx.cwd);
    if (startup.length > 0) contextInjection = `${contextInjection} ${startup}`;
  }
  const memCtx = retrieveMemoryContext(ctx.cwd);
  if (memCtx.length > 0) contextInjection = `${contextInjection} ${memCtx}`;

  const contextSection = contextInjection.length > 0 ? `CONTEXT: ${contextInjection}` : "";

  // human_directive (run.sh:9025-9032).
  const humanInput = envStr(env, "LOKI_HUMAN_INPUT", "");
  const humanDirective =
    humanInput.length > 0
      ? `HUMAN_DIRECTIVE (PRIORITY): ${humanInput} Execute this directive BEFORE continuing normal tasks.`
      : "";

  // queue_tasks (run.sh:9036-9039).
  const rawQueue = loadQueueTasks(ctx.cwd);
  const queueTasks =
    rawQueue.length > 0
      ? `QUEUED_TASKS (PRIORITY): ${rawQueue}. Execute these tasks BEFORE finding new improvements.`
      : "";

  const gateEscalationContext = buildGateEscalationContext(ctx.cwd);

  return {
    contextSection,
    gateFailureContext: await buildGateFailureContext(ctx.cwd, ctx.env),
    gateEscalationContext,
    selfHealContext: buildSelfHealContext(ctx.cwd),
    humanDirective,
    queueTasks,
    appRunnerInfo: buildAppRunnerInfo(ctx.cwd),
    playwrightInfo: buildPlaywrightInfo(ctx.cwd),
    bmadContext: buildBmadContext(ctx.cwd),
    openspecContext: buildOpenspecContext(ctx.cwd),
    mirofishContext: buildMirofishContext(ctx.cwd),
    magicContext: buildMagicContext(ctx.cwd, targetDir),
    checklistStatus: buildChecklistStatus(ctx.cwd, prd, env),
    efficiencyTrend: await buildEfficiencyTrend(ctx.cwd, env),
  };
}

// ---------------------------------------------------------------------------
// Main entry point.
// ---------------------------------------------------------------------------

// A-132: mirror of run.sh _loki_is_quick_prd. Only `loki quick` writes
// .loki/quick-prd-<pid>.md; such a run does not ask for USAGE.md. Bash keys on
// the global PRD_PATH (the ORIGINAL path) because persist_user_prd repoints the
// prompt's $prd to .loki/generated-prd.md. The TS runner carries the original
// on ctx.statePrdPath (threaded as opts.prdPath); env.PRD_PATH is the fallback.
// Bash blanks the instruction in place, so returning "" keeps byte parity.
function usageDocFor(opts: BuildPromptOpts): string {
  const orig = opts.prdPath ?? opts.ctx.env["PRD_PATH"] ?? "";
  return /(^|\/)quick-prd-.*\.md$/s.test(orig) ? "" : USAGE_DOC_INSTRUCTION;
}

export async function buildPrompt(opts: BuildPromptOpts): Promise<string> {
  const { retry, prd, iteration, ctx } = opts;
  const env = ctx.env;

  const phases = buildPhases(env);
  const maxParallel = envInt(env, "MAX_PARALLEL_AGENTS", 10);
  const maxIterations = envInt(env, "MAX_ITERATIONS", 1000);
  const completionPromise = envStr(env, "COMPLETION_PROMISE", "");
  const autonomyMode = envStr(env, "AUTONOMY_MODE", "");
  const perpetualMode = envBool(env, "PERPETUAL_MODE");
  const perpetual = autonomyMode === "perpetual" || perpetualMode;
  const targetDir = envStr(env, "TARGET_DIR", ".");
  // Absolute target dir for the workflow-analysis complexity FS-walk fallback,
  // resolved against the runner cwd so a relative TARGET_DIR (default ".") walks
  // the run's project, not the process cwd. (#584)
  const analysisTargetDir = resolve(ctx.cwd, targetDir);
  const legacyOrdering = envBool(env, "LOKI_LEGACY_PROMPT_ORDERING");
  const providerDegraded = envBool(env, "PROVIDER_DEGRADED");

  // Resolve all variables BEFORE assembling the string (parity hazard).
  // 7.114.0 (rank 8): rarvInstruction is mode-aware. `perpetual` here already
  // folds AUTONOMY_MODE=perpetual || PERPETUAL_MODE; the rarv gate additionally
  // treats an empty COMPLETION_PROMISE as perpetual (parity with the bash split).
  const rarvPerpetual = perpetual || completionPromise.length === 0;
  const rarvText = rarvInstruction(maxParallel, rarvPerpetual);
  const completionText = completionInstruction(completionPromise, iteration, maxIterations);
  const autonomyText = autonomousSuffix(perpetual, completionPromise);
  const sdlcText = sdlcInstruction(phases);
  const sections = await resolveDynamicSections(opts, targetDir);

  // ----- Legacy single-line layout (run.sh:9250-9286) ----------------------
  if (legacyOrdering) {
    if (providerDegraded) {
      return buildLegacyDegraded(opts, sections, prd, retry, iteration);
    }
    // v7.40.0 (#584): same once-per-run autonomous-decision disclosure on the
    // legacy layout's no-PRD path. buildLegacyFull always receives the analysis
    // string but only emits it when there is no PRD, so gate the disclosure the
    // same way.
    if (prd === null || prd.length === 0) {
      maybeDiscloseWorkflowAnalysis(env, analysisTargetDir);
    }
    return buildLegacyFull(opts, {
      rarvText,
      completionText,
      autonomyText,
      sdlcText,
      analysis: analysisInstruction(env, analysisTargetDir),
      memory: MEMORY_INSTRUCTION,
      docScope: docScopeInstruction(env),
      sections,
    });
  }

  // DOC_SCOPE (F52): tier-resolved once, cache-stable within a run. Threaded to
  // the degraded path and emitted inline below alongside USAGE_DOC_INSTRUCTION.
  const docScope = docScopeInstruction(env);

  // ----- Degraded provider (run.sh:9304-9334) ------------------------------
  if (providerDegraded) {
    return buildStaticFirstDegraded(opts, sections, docScope);
  }

  // ----- Full static-first layout (run.sh:9336-9381) -----------------------
  const lines: string[] = [];
  const prdAnchor = prd !== null && prd.length > 0 ? `Loki Mode with PRD at ${prd}` : "Loki Mode";
  lines.push("<loki_system>");
  lines.push(prdAnchor);
  // LOKI_SIMPLE=1 -- THE ABLATION ARM. Byte-mirrored with run.sh; edit BOTH or
  // the build_prompt parity fixtures diverge and the Bun Parity job blocks.
  //
  // Default off, so the emitted bytes are unchanged unless it is explicitly
  // set and all 61 fixtures under tests/fixtures/build_prompt hold.
  //
  // WHY. Anthropic deleted ~80% of Claude Code's system prompt for Opus 5 on
  // the finding that instructions written to correct older models had become
  // dead weight, and that the model measured slightly MORE capable without
  // them. Their method was ablation: delete, measure, add back only what a
  // measured failure demands. Nothing in this prefix had ever been measured.
  //
  // The strip is COACHING ONLY -- how to work (RARV cycle, SDLC phases,
  // memory habits), which a frontier model does natively. The dynamic tail is
  // STATE -- which gate failed, what self-heal found -- and is untouched. That
  // boundary is the safety argument: deleting coaching drops a lecture,
  // deleting state would make the run blind to its own history.
  //
  // MEASURED, and the provenance matters: 8026 -> 1779 bytes (-78%, ~1562
  // tokens/iteration) from a LIVE buildPrompt call with a gate-failure file
  // present, not from a fixture. fixture-1 on disk is 7909 bytes; an earlier
  // version of this comment cited "fixture-1: 8090 -> 1776" and was wrong
  // about WHERE the number came from, which is exactly the kind of confident
  // mis-sourcing that turns a real measurement into an unreproducible claim.
  //
  // Note the strip is bounded: only the nine pushes below are gated, so
  // <loki_system>, the PRD anchor, the goal-score advisory and the closing tag
  // all survive. The prefix size is therefore a CEILING on the saving, never
  // the saving itself.
  //
  // Gates, receipts and verification are NEVER an ablation arm; the trust core
  // is not prompt correction.
  const simple = (env.LOKI_SIMPLE ?? "0") === "1";
  if (!simple) {
  lines.push(rarvText);
  lines.push(sdlcText);
  lines.push(autonomyText);
  lines.push(MEMORY_INSTRUCTION);
  lines.push(usageDocFor(opts));
  lines.push(docScope);
  lines.push(COMPOSE_INSTRUCTION);
  lines.push(LSP_GROUNDING_INSTRUCTION);
  lines.push(AGENTS_MD_INSTRUCTION);
  }
  // v8 harness intelligence (3c): flag a goal the loop cannot hill-climb.
  // Derived from COMPLETION_PROMISE, fixed for the run, so it is cache-stable
  // and belongs here in the prefix (above [CACHE_BREAKPOINT]) rather than in
  // <dynamic_context>, where it would bust the cache every iteration.
  //
  // Advisory ONLY: "" for a measurable goal (or when scoring is disabled), and
  // it never blocks a build or edits the user's goal. Deliberately not added to
  // the DEGRADED path below, which carries a minimal instruction set by design.
  //
  // SUPPRESSED IN PERPETUAL MODE. Perpetual runs are open-ended on purpose
  // ("never ending improvement cycle"); an unbounded goal is the CONFIGURATION
  // there, not a defect, so demanding a success threshold would be advice
  // against the mode the user explicitly chose.
  const goalSharpening = perpetual ? "" : goalSharpeningInstruction(completionPromise, env);
  if (goalSharpening.length > 0) lines.push(goalSharpening);

  // Harness intelligence (feature 6): evidence-backed repository profile.
  // Cache-stable for the same reason as the goal advisory above -- the profile
  // is derived from repo manifest files, hash-invalidated and TTL-bounded, so it
  // does not change between iterations. It therefore belongs in the prefix, NOT
  // in <dynamic_context> where it would bust the prompt cache every iteration.
  //
  // DEFAULT OFF (LOKI_REPO_PROFILE): profileFragment returns "" with the flag
  // unset, and also whenever the profile is anything other than fresh. That
  // empty-string default is what keeps the 60 byte-exact parity fixtures green,
  // since they build with an injected env object carrying no such flag.
  //
  // Not added to the DEGRADED path below, matching goalSharpening: that path
  // carries a minimal instruction set by design.
  // lokiDirOverride is threaded explicitly: the writer (autonomous.ts, once per
  // run) passes ctx.lokiDir, while repo_profile's default resolves from
  // process.cwd()/LOKI_DIR. When those differ the write and the read address
  // different files, and the fragment would silently stay empty forever -- a
  // false-green that no flag-off test could ever catch. Same value, both sides.
  const repoProfile = profileFragment({
    repoRoot: ctx.cwd,
    lokiDirOverride: envStr(env, "LOKI_DIR", "") || undefined,
    env,
  });
  if (repoProfile.length > 0) lines.push(repoProfile);
  if (prd === null || prd.length === 0) {
    // v7.40.0 (#584): emit the autonomous-decision cost disclosure once per run
    // BEFORE pushing the (possibly workflow-prefixed) analysis instruction. The
    // module latch makes this fire once even though buildPrompt runs per
    // iteration. No-op unless the unset-var + complexity=complex branch fired.
    maybeDiscloseWorkflowAnalysis(env, analysisTargetDir);
    lines.push(analysisInstruction(env, analysisTargetDir));
  }
  lines.push("</loki_system>");
  lines.push("[CACHE_BREAKPOINT]");
  lines.push(`<dynamic_context iteration="${iteration}" retry="${retry}">`);

  if (retry > 0) {
    if (prd !== null && prd.length > 0) {
      lines.push(`Resume iteration #${iteration} (retry #${retry}). PRD: ${prd}`);
    } else {
      lines.push(`Resume iteration #${iteration} (retry #${retry}). Use .loki/generated-prd.md if exists.`);
    }
  }
  if (sections.humanDirective.length > 0) lines.push(sections.humanDirective);
  if (sections.gateFailureContext.length > 0) lines.push(sections.gateFailureContext);
  if (sections.gateEscalationContext.length > 0) lines.push(sections.gateEscalationContext);
  if (sections.selfHealContext.length > 0) lines.push(sections.selfHealContext);
  if (sections.queueTasks.length > 0) lines.push(sections.queueTasks);
  if (sections.bmadContext.length > 0) lines.push(sections.bmadContext);
  if (sections.openspecContext.length > 0) lines.push(sections.openspecContext);
  if (sections.mirofishContext.length > 0) lines.push(sections.mirofishContext);
  if (sections.magicContext.length > 0) lines.push(sections.magicContext);
  if (sections.checklistStatus.length > 0) lines.push(sections.checklistStatus);
  if (sections.appRunnerInfo.length > 0) lines.push(sections.appRunnerInfo);
  if (sections.playwrightInfo.length > 0) lines.push(sections.playwrightInfo);
  if (sections.contextSection.length > 0) lines.push(sections.contextSection);
  // Volatile by definition (changes every iteration), so it belongs here inside
  // <dynamic_context>, never in the cache-stable <loki_system> prefix -- putting
  // it above [CACHE_BREAKPOINT] would bust the prompt cache every iteration.
  if (sections.efficiencyTrend.length > 0) lines.push(sections.efficiencyTrend);
  lines.push(completionText);
  lines.push("</dynamic_context>");

  // bash printf '%s\n' on every section emits a trailing newline -- match that.
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// Static-first degraded (run.sh:9304-9334).
// ---------------------------------------------------------------------------

function buildStaticFirstDegraded(
  opts: BuildPromptOpts,
  sections: ResolvedSections,
  docScope: string,
): string {
  const { prd, iteration, retry, ctx } = opts;
  let prdContent = "";
  if (prd !== null && prd.length > 0) {
    const abs = resolve(ctx.cwd, prd);
    const raw = readBytesSafe(abs, 4000);
    prdContent = raw ?? "";
  }
  const anchor = prd !== null && prd.length > 0 ? "Loki Mode with PRD" : "Loki Mode";
  const lines: string[] = [];
  lines.push("<loki_system>");
  lines.push(anchor);
  if (prd !== null && prd.length > 0) {
    lines.push(
      "You are a coding assistant. Read and implement the requirements from the PRD. Write working code, run tests if possible, and commit changes.",
    );
  } else {
    lines.push(
      "You are a coding assistant. Analyze this codebase and suggest improvements. Write working code and commit changes.",
    );
  }
  lines.push(usageDocFor(opts));
  lines.push(docScope);
  lines.push(COMPOSE_INSTRUCTION);
  lines.push(LSP_GROUNDING_INSTRUCTION);
  lines.push(AGENTS_MD_INSTRUCTION);
  lines.push("</loki_system>");
  lines.push("[CACHE_BREAKPOINT]");
  lines.push(`<dynamic_context iteration="${iteration}" retry="${retry}">`);
  if (sections.humanDirective.length > 0) lines.push(`Priority: ${sections.humanDirective}`);
  if (sections.gateEscalationContext.length > 0) lines.push(sections.gateEscalationContext);
  if (sections.queueTasks.length > 0) lines.push(`Tasks: ${sections.queueTasks}`);
  if (prd !== null && prd.length > 0) lines.push(`PRD contents: ${prdContent}`);
  lines.push("</dynamic_context>");
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// Legacy ordering -- single echo line (run.sh:9252-9285).
// ---------------------------------------------------------------------------

interface LegacyFullParts {
  rarvText: string;
  completionText: string;
  autonomyText: string;
  sdlcText: string;
  analysis: string;
  memory: string;
  docScope: string;
  sections: ResolvedSections;
}

function buildLegacyFull(opts: BuildPromptOpts, p: LegacyFullParts): string {
  const { prd, retry, iteration } = opts;
  const s = p.sections;
  const combinedGateContext = [s.gateFailureContext, s.gateEscalationContext]
    .filter((part) => part.length > 0)
    .join(" ");
  // Order from run.sh:9273-9281. Empty optional sections are emitted as empty
  // strings between two spaces, exactly as bash's "$var $var" expansion does.
  const tail = [
    s.humanDirective,
    combinedGateContext,
    s.queueTasks,
    s.bmadContext,
    s.openspecContext,
    s.mirofishContext,
    s.magicContext,
    s.checklistStatus,
    s.appRunnerInfo,
    s.playwrightInfo,
    s.contextSection,
  ].join(" ");

  if (retry === 0) {
    if (prd !== null && prd.length > 0) {
      return `Loki Mode with PRD at ${prd}. ${tail} ${p.rarvText} ${p.memory} ${usageDocFor(opts)} ${p.docScope} ${COMPOSE_INSTRUCTION} ${LSP_GROUNDING_INSTRUCTION} ${AGENTS_MD_INSTRUCTION} ${p.completionText} ${p.sdlcText} ${p.autonomyText}\n`;
    }
    return `Loki Mode. ${tail} ${p.analysis} ${p.rarvText} ${p.memory} ${usageDocFor(opts)} ${p.docScope} ${COMPOSE_INSTRUCTION} ${LSP_GROUNDING_INSTRUCTION} ${AGENTS_MD_INSTRUCTION} ${p.completionText} ${p.sdlcText} ${p.autonomyText}\n`;
  }
  if (prd !== null && prd.length > 0) {
    return `Loki Mode - Resume iteration #${iteration} (retry #${retry}). PRD: ${prd}. ${tail} ${p.rarvText} ${p.memory} ${usageDocFor(opts)} ${p.docScope} ${COMPOSE_INSTRUCTION} ${LSP_GROUNDING_INSTRUCTION} ${AGENTS_MD_INSTRUCTION} ${p.completionText} ${p.sdlcText} ${p.autonomyText}\n`;
  }
  return `Loki Mode - Resume iteration #${iteration} (retry #${retry}). ${tail} Use .loki/generated-prd.md if exists. ${p.rarvText} ${p.memory} ${usageDocFor(opts)} ${p.docScope} ${COMPOSE_INSTRUCTION} ${LSP_GROUNDING_INSTRUCTION} ${AGENTS_MD_INSTRUCTION} ${p.completionText} ${p.sdlcText} ${p.autonomyText}\n`;
}

function buildLegacyDegraded(
  opts: BuildPromptOpts,
  sections: ResolvedSections,
  prd: string | null,
  retry: number,
  iteration: number,
): string {
  const { ctx } = opts;
  let prdContent = "";
  if (prd !== null && prd.length > 0) {
    const abs = resolve(ctx.cwd, prd);
    prdContent = readBytesSafe(abs, 4000) ?? "";
  }
  // bash `${var:+prefix $var}` -- if var is non-empty, output `prefix $var`,
  // else nothing. Exactly two spaces around each segment in bash's echo.
  const priorityContext = [sections.humanDirective, sections.gateEscalationContext]
    .filter((part) => part.length > 0)
    .join(" ");
  const human = priorityContext.length > 0 ? `Priority: ${priorityContext}` : "";
  const tasks = sections.queueTasks.length > 0 ? `Tasks: ${sections.queueTasks}` : "";

  if (retry === 0) {
    if (prd !== null && prd.length > 0) {
      return `You are a coding assistant. Read and implement the requirements from the PRD below. Write working code, run tests if possible, and commit changes. ${human} ${tasks} PRD contents: ${prdContent}\n`;
    }
    return `You are a coding assistant. Analyze this codebase and suggest improvements. Write working code and commit changes. ${human} ${tasks}\n`;
  }
  if (prd !== null && prd.length > 0) {
    return `You are a coding assistant. Continue working on iteration ${iteration}. Review what exists, implement remaining PRD requirements, fix any issues, add tests. ${human} ${tasks} PRD contents: ${prdContent}\n`;
  }
  return `You are a coding assistant. Continue working on iteration ${iteration}. Review what exists, improve code, fix bugs, add tests. ${human} ${tasks}\n`;
}

